CREATE TABLE IF NOT EXISTS performance_blueprints(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),contract_id UUID NOT NULL,contract_version_id UUID NOT NULL,agreement_intelligence_version_id UUID NOT NULL,version INTEGER NOT NULL,status TEXT NOT NULL CHECK(status IN('DRAFT','ACTIVE','SUPERSEDED')),created_by UUID NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),content_hash TEXT NOT NULL,UNIQUE(contract_id,version));
CREATE TABLE IF NOT EXISTS scope_items(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),blueprint_id UUID NOT NULL REFERENCES performance_blueprints(id),kind TEXT NOT NULL CHECK(kind IN('INCLUDED','EXCLUDED')),description TEXT NOT NULL,assumptions JSONB NOT NULL,constraints JSONB NOT NULL,owner_id UUID,status TEXT NOT NULL CHECK(status IN('DRAFT','CONFIRMED')),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS deliverables(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),blueprint_id UUID NOT NULL REFERENCES performance_blueprints(id),scope_item_id UUID NOT NULL REFERENCES scope_items(id),title TEXT NOT NULL,quantity NUMERIC NOT NULL CHECK(quantity>0),unit TEXT NOT NULL,quality_standard TEXT NOT NULL,owner_id UUID NOT NULL,due_date DATE NOT NULL,acceptance_criteria JSONB NOT NULL CHECK(jsonb_array_length(acceptance_criteria)>0),evidence_requirements JSONB NOT NULL CHECK(jsonb_array_length(evidence_requirements)>0),status TEXT NOT NULL CHECK(status IN('DRAFT','CONFIRMED')),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS blueprint_milestones(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),blueprint_id UUID NOT NULL REFERENCES performance_blueprints(id),title TEXT NOT NULL,deliverable_ids JSONB NOT NULL CHECK(jsonb_array_length(deliverable_ids)>0),start_date DATE NOT NULL,due_date DATE NOT NULL,budget_amount_minor BIGINT NOT NULL CHECK(budget_amount_minor>0),currency TEXT NOT NULL,value_allocation_percent NUMERIC NOT NULL CHECK(value_allocation_percent>0 AND value_allocation_percent<=100),status TEXT NOT NULL CHECK(status IN('SCHEDULED','CANCELLED')),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS milestone_sequence_edges(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),blueprint_id UUID NOT NULL REFERENCES performance_blueprints(id),predecessor_id UUID NOT NULL REFERENCES blueprint_milestones(id),successor_id UUID NOT NULL REFERENCES blueprint_milestones(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),CHECK(predecessor_id<>successor_id),UNIQUE(predecessor_id,successor_id));
CREATE TABLE IF NOT EXISTS dod_packages(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),milestone_id UUID NOT NULL REFERENCES blueprint_milestones(id),version INTEGER NOT NULL,deliverable_gate_ids JSONB NOT NULL CHECK(jsonb_array_length(deliverable_gate_ids)>0),criteria JSONB NOT NULL,evidence_requirements JSONB NOT NULL CHECK(jsonb_array_length(evidence_requirements)>0),quality_gate BOOLEAN NOT NULL,compliance_gate BOOLEAN NOT NULL,risk_gate BOOLEAN NOT NULL,payment_gate BOOLEAN NOT NULL,status TEXT NOT NULL CHECK(status IN('DRAFT','PUBLISHED','SUPERSEDED')),created_by UUID NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),content_hash TEXT NOT NULL,UNIQUE(milestone_id,version));
CREATE INDEX IF NOT EXISTS performance_blueprints_contract_idx ON performance_blueprints(workspace_id,contract_id);CREATE INDEX IF NOT EXISTS scope_items_blueprint_idx ON scope_items(workspace_id,blueprint_id);CREATE INDEX IF NOT EXISTS deliverables_blueprint_idx ON deliverables(workspace_id,blueprint_id);CREATE INDEX IF NOT EXISTS blueprint_milestones_blueprint_idx ON blueprint_milestones(workspace_id,blueprint_id);CREATE INDEX IF NOT EXISTS dod_packages_milestone_idx ON dod_packages(workspace_id,milestone_id);
ALTER TABLE performance_blueprints ENABLE ROW LEVEL SECURITY;ALTER TABLE scope_items ENABLE ROW LEVEL SECURITY;ALTER TABLE deliverables ENABLE ROW LEVEL SECURITY;ALTER TABLE blueprint_milestones ENABLE ROW LEVEL SECURITY;ALTER TABLE milestone_sequence_edges ENABLE ROW LEVEL SECURITY;ALTER TABLE dod_packages ENABLE ROW LEVEL SECURITY;
DO $$ DECLARE t TEXT;BEGIN FOREACH t IN ARRAY ARRAY['performance_blueprints','scope_items','deliverables','blueprint_milestones','milestone_sequence_edges','dod_packages'] LOOP BEGIN EXECUTE format('CREATE POLICY %I ON %I USING(workspace_id=current_workspace_id() AND has_active_workspace_membership(workspace_id))',t||'_workspace',t);EXCEPTION WHEN duplicate_object THEN NULL;END;END LOOP;END $$;
DO $$ DECLARE t TEXT;BEGIN FOREACH t IN ARRAY ARRAY['performance_blueprints','scope_items','deliverables','blueprint_milestones','milestone_sequence_edges','dod_packages'] LOOP BEGIN EXECUTE format('CREATE TRIGGER %I BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION prevent_append_only_mutation()',t||'_append_only',t);EXCEPTION WHEN duplicate_object THEN NULL;END;END LOOP;END $$;
